using System.Text;
using System.Text.Json;
using Dsh.RemoteHost;

namespace Dsh.WebBridge;

/** Public wire metadata, generated by the serving process; never a claim about a connected host's supported domains. */
internal static class BrowserProtocol
{
    public const string Path = "/protocol.js";

    public static readonly StaticAsset Asset = CreateAsset();

    private static StaticAsset CreateAsset()
    {
        var script = new StringBuilder();
        Export(script, "SessionStatus", new Dictionary<string, string>(StringComparer.Ordinal)
        {
            [nameof(HostSessionStatuses.Running)] = HostSessionStatuses.Running,
            [nameof(HostSessionStatuses.WaitingForUser)] = HostSessionStatuses.WaitingForUser,
            [nameof(HostSessionStatuses.Idle)] = HostSessionStatuses.Idle,
            [nameof(HostSessionStatuses.Exited)] = HostSessionStatuses.Exited,
        });
        Export(script, "SessionKind", new Dictionary<string, string>(StringComparer.Ordinal)
        {
            [nameof(HostSessionKinds.Harness)] = HostSessionKinds.Harness,
            [nameof(HostSessionKinds.External)] = HostSessionKinds.External,
            [nameof(HostSessionKinds.Acp)] = HostSessionKinds.Acp,
            [nameof(HostSessionKinds.Terminal)] = HostSessionKinds.Terminal,
        });
        Export(script, "Capability", HostProtocolCatalog.KnownCapabilities);
        Export(script, "AgentMode", new Dictionary<string, string>(StringComparer.Ordinal)
        {
            [nameof(RemoteAgentModes.Terminal)] = RemoteAgentModes.Terminal,
            [nameof(RemoteAgentModes.Acp)] = RemoteAgentModes.Acp,
        });
        return new StaticAsset(Encoding.UTF8.GetBytes(script.ToString()), "text/javascript; charset=utf-8");
    }

    private static void Export(StringBuilder script, string name, IReadOnlyDictionary<string, string> values)
    {
        script.Append("export const ").Append(name).Append(" = Object.freeze(");
        script.Append(JsonSerializer.Serialize(values, WebBridgeJsonContext.Default.IReadOnlyDictionaryStringString));
        script.Append(");\n");
    }
}
